stages.sampleAnswer:
POST /deposits
  body: { amount, bankAccountId }, header: Idempotency-Key
  → 201 { txId, status: PENDING }

POST /orders
  body: { symbol, side: BUY|SELL, orderType: MARKET|LIMIT, quantity, limitPrice? }, header: Idempotency-Key
  → 201 { orderId, status: PENDING }

DELETE /orders/:orderId
  → 204

GET /portfolio
  → 200 { cashBalance, holdings: [{ symbol, quantity, avgCostBasis }] }

WS /prices/:symbol
  → { symbol, bid, ask, last, timestamp }
  (streaming updates)
